// Unit tests for the size gate's scope, counting and config parsing (LAB-7587).
// node:test only. Every expectation is a literal, never computed by the code
// under test.
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { inScope, isGenerated, language, exemptByText } from "./scope.mjs";
import { lineCount, measureTree } from "./measure.mjs";
import { parseConfig, pathspecs, UsageError } from "./config.mjs";

test("in scope: the four languages, nothing else", () => {
  for (const p of ["a.go", "ui/x.ts", "ui/X.tsx", "pkg/m.py"]) assert.equal(inScope(p), true, p);
  for (const p of ["a.mjs", "a.js", "a.java", "README.md", "a.d.ts", "api.pb.go"])
    assert.equal(inScope(p), false, p);
});

test("AC7 test-name patterns are exempt", () => {
  for (const p of [
    "x_test.go",
    "ui/x.test.ts",
    "ui/x.spec.tsx",
    "pkg/test_x.py",
    "pkg/x_test.py",
    "pkg/conftest.py",
  ])
    assert.equal(inScope(p), false, p);
  for (const p of ["pkg/latest_x.py", "pkg/contest.py", "pkg/x_tester.py"]) assert.equal(inScope(p), true, p);
});

test("generic test, vendor and generated directories are exempt", () => {
  for (const p of [
    "vendor/a.go",
    "node_modules/a.ts",
    "a/mocks/m.go",
    "a/__mocks__/m.ts",
    "a/generated/g.py",
    "a/e2e/s.ts",
    "a/x_gen.go",
    "a/x.gen.ts",
    "a/zz_generated.deepcopy.go",
    "zz_generated.deepcopy.go",
    "a/__tests__/t.ts",
    "a/testdata/t.go",
    "a/fixtures/f.py",
    "a/tests/t.py",
    "a/testutils.go",
  ])
    assert.equal(inScope(p), false, p);
  // zz_generated must start the filename; a hand-written name that merely contains it is measured.
  for (const p of ["pkg/jazz_generated.py", "pkg/util_zz_generated.go"]) assert.equal(inScope(p), true, p);
  // zz_generated names a file, not a directory: a hand-written file under such a directory is measured.
  assert.equal(inScope("pkg/zz_generated_helpers/manual.go"), true);
  assert.equal(inScope("pkg/zz_generated.deepcopy.go"), false);
});

test("language by extension", () => {
  assert.equal(language("a.go"), "go");
  assert.equal(language("a.ts"), "ts");
  assert.equal(language("a.tsx"), "tsx");
  assert.equal(language("a.py"), "py");
  assert.equal(language("a.mjs"), null);
});

test("isGenerated: standard header before code only", () => {
  assert.equal(isGenerated("// Code generated by protoc. DO NOT EDIT.\npackage p\n"), true);
  assert.equal(isGenerated("/* licence\n spans */\n// Code generated by x. DO NOT EDIT.\npackage p\n"), true);
  assert.equal(isGenerated("package p\n// Code generated by x. DO NOT EDIT.\n"), false);
  assert.equal(isGenerated('package p\nvar s = "// Code generated by x. DO NOT EDIT."\n'), false);
  assert.equal(isGenerated("// Code generated by x. Do not edit.\npackage p\n"), false);
  // Go strips \r from comment text, so a CRLF header still counts.
  assert.equal(isGenerated("// Code generated by x. DO NOT EDIT.\r\n\r\npackage a\r\n"), true);
  assert.equal(isGenerated("package a\r\n// Code generated by x. DO NOT EDIT.\r\n"), false);
});

test("isGenerated: the header counts after any number of leading comment or blank lines", () => {
  const lead = Array.from({ length: 250 }, (_, i) => (i % 2 ? "" : `// licence ${i}`)).join("\n");
  assert.equal(isGenerated(`${lead}\n// Code generated by x. DO NOT EDIT.\npackage p\n`), true);
  assert.equal(isGenerated(`${lead}\npackage p\n// Code generated by x. DO NOT EDIT.\n`), false);
});

test("exemptByText applies the generated header to Go only", () => {
  const header = "// Code generated by x. DO NOT EDIT.\n";
  assert.equal(exemptByText("a.go", header), true);
  assert.equal(exemptByText("a.ts", header), false);
  assert.equal(exemptByText("a.go", "package p\n"), false);
});

test("lineCount counts physical lines; a last line without newline counts", () => {
  assert.equal(lineCount("a.go", ""), 1); // ported verbatim: the port counts an empty file as one line
  assert.equal(lineCount("a.go", "a"), 1);
  assert.equal(lineCount("a.go", "a\n"), 1);
  assert.equal(lineCount("a.go", "a\n\nb"), 3);
  assert.equal(lineCount("a.go", "a\n// c\n\n"), 3);
});

test("lineCount breaks lines where each language's parser does", () => {
  const t = "a\r\nb\rc\u2028d\u2029e\n";
  assert.deepEqual(["a.go", "a.py", "a.ts", "a.tsx"].map((p) => lineCount(p, t)), [2, 3, 5, 5]);
  for (const p of ["a.go", "a.py", "a.ts"]) assert.equal(lineCount(p, "a\r\nb\r\n"), 2, `${p}: CRLF counts as today`);
});

test("measureTree measures in-scope regular files and skips the rest", () => {
  const root = mkdtempSync(path.join(tmpdir(), "sg-measure-"));
  mkdirSync(path.join(root, "d"));
  writeFileSync(path.join(root, "d/a.go"), "package p\n\nfunc A() {}\n");
  writeFileSync(path.join(root, "d/g.go"), "// Code generated by x. DO NOT EDIT.\npackage p\n");
  writeFileSync(path.join(root, "d/a_test.go"), "package p\n");
  writeFileSync(path.join(root, "d/m.py"), "x = 1\ny = 2");
  const loc = measureTree(root, ["d/a.go", "d/g.go", "d/a_test.go", "d/m.py", "d/gone.ts"]);
  assert.deepEqual([...loc].sort(), [
    ["d/a.go", 3],
    ["d/m.py", 2],
  ]);
});

test("parseConfig: flags, env fallbacks and defaults", () => {
  const c = parseConfig(["check", "--root", "repo", "--include", "a/**", "--include", "b/**", "--exclude", "c/**"], {});
  assert.equal(c.mode, "check");
  assert.equal(c.root, path.resolve("repo"));
  assert.equal(c.baselinePath, ".github/size-baseline.json");
  assert.deepEqual(c.include, ["a/**", "b/**"]);
  assert.deepEqual(c.exclude, ["c/**"]);
  assert.equal(c.minScanned, 1);
  assert.equal(c.pullRequest, false);
  assert.equal(parseConfig(["check"], { GITHUB_EVENT_NAME: "pull_request" }).pullRequest, true);
  const e = parseConfig(["baseline"], {
    SIZE_GATE_BASELINE: "x/b.json",
    SIZE_GATE_INCLUDE: "a/**\n\n  b/**  \n",
    SIZE_GATE_EXCLUDE: "acceptance/**",
    SIZE_GATE_MIN_SCANNED: "2000",
  });
  assert.equal(e.baselinePath, "x/b.json");
  assert.deepEqual(e.include, ["a/**", "b/**"]);
  assert.deepEqual(e.exclude, ["acceptance/**"]);
  assert.equal(e.minScanned, 2000);
});

test("parseConfig refuses unknown modes, flags and bad numbers", () => {
  assert.throws(() => parseConfig([], {}), UsageError);
  assert.throws(() => parseConfig(["functions"], {}), UsageError);
  assert.throws(() => parseConfig(["check", "--bogus"], {}), UsageError);
  assert.throws(() => parseConfig(["check", "--root"], {}), UsageError);
  assert.throws(() => parseConfig(["check", "--min-scanned", "-1"], {}), UsageError);
  assert.throws(() => parseConfig(["check"], { SIZE_GATE_MIN_SCANNED: "lots" }), UsageError);
});

test("pathspecs: include and exclude become git glob magic", () => {
  assert.deepEqual(pathspecs([], []), []);
  assert.deepEqual(pathspecs(["ui/**"], ["acceptance/**"]), [":(glob)ui/**", ":(exclude,glob)acceptance/**"]);
});
